import unittest,re
from tools.kjv_archive import load_register,read
class PeterRememberedVoicesTests(unittest.TestCase):
 def test_remembered_voices_and_dissolution(self):
  prior,_=load_register('0.10-kjv.265');lang,manifest=load_register('0.10-kjv.266')
